export interface SqSKU { id:string; name:string; cat:string; badge:string; w:number; ship:number; stock:number; imgs:string[]; }
export const calcSq = (w:number, ship:number) => { const r = +(w * (w > 100 ? 1.08 : 1.1)).toFixed(2), tax = +(r * 0.0825).toFixed(2), tot = +((r + ship + tax + 0.3) / 0.971).toFixed(2); return { r, ship, tax, fee: +(tot - r - ship - tax).toFixed(2), tot }; };
